gameActivityImportAdditions.insert:


import com.google.android.gms.ads.MobileAds;
import com.google.android.gms.ads.AdRequest;
import com.google.android.gms.ads.AdError;
import com.google.android.gms.ads.LoadAdError;
import com.google.android.gms.ads.FullScreenContentCallback;
import com.google.android.gms.ads.interstitial.InterstitialAd;
import com.google.android.gms.ads.interstitial.InterstitialAdLoadCallback;

gameActivityClassAdditions.insert:


private InterstitialAd ABUE_InterstitialAd = null;


// =========================================================
// JAVA -> C++ CALLBACKS
// =========================================================

public native void nativeABUEInterstitialLoaded();

public native void nativeABUEInterstitialLoadFailed(
    int errorCode,
    String errorDomain,
    String errorMessage
);

public native void nativeABUEInterstitialShown();

public native void nativeABUEInterstitialShowFailed(
    int errorCode,
    String errorDomain,
    String errorMessage
);

public native void nativeABUEInterstitialClosed();



// =========================================================
// LOAD
// =========================================================

public void ABUE_LoadInterstitial()
{
    runOnUiThread(() ->
    {
        AdRequest adRequest =
            new AdRequest.Builder().build();


        InterstitialAd.load(
            GameActivity.this,
            ABUE_INTERSTITIAL_AD_UNIT_ID,
            adRequest,

            new InterstitialAdLoadCallback()
            {
                @Override
                public void onAdLoaded(
                    InterstitialAd interstitialAd
                )
                {
                    ABUE_InterstitialAd = interstitialAd;

                    nativeABUEInterstitialLoaded();
                }


                @Override
                public void onAdFailedToLoad(
                    LoadAdError loadAdError
                )
                {
                    ABUE_InterstitialAd = null;
                    android.util.Log.e(
                        "AdBridgeUE",
                        loadAdError.toString()
                    );

                    nativeABUEInterstitialLoadFailed(
                        loadAdError.getCode(),
                        loadAdError.getDomain(),
                        loadAdError.getMessage()
                    );
                }
            }
        );
    });
}



// =========================================================
// SHOW
// =========================================================

public void ABUE_ShowInterstitial()
{
    runOnUiThread(() ->
    {
        if (ABUE_InterstitialAd == null)
        {
            nativeABUEInterstitialShowFailed(
                -1,
                "AdBridgeUE.Java",
                "Interstitial is not loaded."
            );

            return;
        }


        ABUE_InterstitialAd.setFullScreenContentCallback(
            new FullScreenContentCallback()
            {
                @Override
                public void onAdShowedFullScreenContent()
                {
                    nativeABUEInterstitialShown();
                }


                @Override
                public void onAdFailedToShowFullScreenContent(
                    AdError adError
                )
                {
                    ABUE_InterstitialAd = null;

                    android.util.Log.e(
                        "AdBridgeUE",
                        adError.toString()
                    );

                    nativeABUEInterstitialShowFailed(
                        adError.getCode(),
                        adError.getDomain(),
                        adError.getMessage()
                    );
                }


                @Override
                public void onAdDismissedFullScreenContent()
                {
                    ABUE_InterstitialAd = null;

                    nativeABUEInterstitialClosed();
                }
            }
        );


        ABUE_InterstitialAd.show(
            GameActivity.this
        );
    });
}
